save(57,dict(paragraphs=["Nandini Sahu is a poet, fiction writer and scholar of folklore and English literature. Her academic work at Indira Gandhi National Open University has included teaching English and directing its School of Foreign Languages. Her books range from poetry and literary criticism to folk studies and short fiction, including Sita, Zero Point and Shedding the Metaphors.","In the poems gathered here, intimate experience meets myth and a searching view of the self. ‘Manthan’ draws on the churning of the ocean to imagine love through both nectar and poison. ‘My Sense of the World’ holds an ideal of everyday kindness beside uncertainty and hurt, while ‘My Tranquil City, Tonight’ places a troubled address to a beloved against the apparent calm of the city."],sources=[source('IGNOU — Nandini Sahu academic CV','https://www.ignou.ac.in/viewFile/SOH/profile/nandini-cv.pdf',['English teaching and former School of Foreign Languages directorship','Folklore/literary research and publication bibliography','Sita 2014, Zero Point 2018, Shedding the Metaphors 2023']),source('The Criterion — Sita book review','https://www.the-criterion.com/sita-by-nandini-sahu/',['Sita by Nandini Sahu, The Poetry Society of India, 2014, ISBN 9789383888191']),source('Creative Saplings — Shedding the Metaphors review','https://www.creativesaplings.in/index.php/1/article/view/677',['Short-story collection, Black Eagle Books, ISBN 9781645603481'],access='search_index_excerpt')],books=[dict(title='Sita (A Poem)',detail='Long narrative poem. The Poetry Society of India, 2014.',url='https://www.the-criterion.com/sita-by-nandini-sahu/'),dict(title='Shedding the Metaphors',detail='Short-story collection. Black Eagle Books, 2023.',url='https://www.creativesaplings.in/index.php/1/article/view/677')],identity_match='IGNOU English faculty and former Foreign Languages directorship uniquely match captured biography; CV lists same creative/research disciplines. Not astrophysicist namesake.',poems_read=[dict(id=785,title='MY TRANQUIL CITY, TONIGHT',basis='Full English original: retold love, calm city and unresolved emotional address, battlefield/moth/pebble imagery.'),dict(id=517,title='Manthan—A Ghazal',basis='Full English original: Samudra Manthan, nectar/poison, love and renunciation.'),dict(id=511,title='My Sense of the World',basis='Full English original: community kindness and gardens move into hurt, coping and uncertainty.'),dict(id=43,title='Manthan',basis='Full earlier English publication of same poem, including minor typography/punctuation differences; retained independently.')],limitations=['No bestselling claim, exact book total or award added.','CV also lists a Hindi University vice-chancellorship; concise profile avoids asserting its present status.','CV lists a 2025 Sita edition as well as 2014; book card explicitly identifies the reviewed 2014 edition.','43 and 517 repeat Manthan with minor differences; both publication records preserved, not merged.','Mythology and emotional relationships discussed as poetry, not factual biography.','Creative Saplings direct fetch error; indexed bibliographic text plus opened university CV support book entry.'],research_leads=[],next_action='Independent author/editor review and any preferred publication/appointment updates.'))
